//=============================================================================
// VNArabizer_RTL.js
//=============================================================================
/*:
 * @target MZ
 * @plugindesc Arabic support: right-to-left text, joined letters, Arabic font. (VN Arabizer)
 * @author VN Arabizer
 *
 * @help
 * Generated by VN Arabizer. Remove it with the app's "Remove" button,
 * which also restores the original data files.
 *
 * - Loads an Arabic font (fonts/VNArabic-Regular.ttf) in front of the
 *   game's own font, so untranslated Japanese text still shows.
 * - Draws Arabic with the browser's shaping, so letters join correctly.
 * - MV: lays message text out right-to-left while keeping the
 *   letter-by-letter typing effect, colour codes and icons.
 * - MZ: uses MZ's built-in right-to-left support.
 * - Right-aligns Arabic menu text.
 */

(function () {
    "use strict";

    var FONT_FAMILY = "VNArabic";
    var FONT_FILE = "VNArabic-Regular.ttf";
    var ALIGN_MENUS_RIGHT = true;
    var ARABIC = /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿]/;

    function hasArabic(s) {
        return typeof s === "string" && ARABIC.test(s);
    }

    var isMZ = typeof Utils !== "undefined" && Utils.RPGMAKER_NAME === "MZ";

    //-------------------------------------------------------------------------
    // Font
    //-------------------------------------------------------------------------
    if (isMZ) {
        var _Scene_Boot_loadGameFonts = Scene_Boot.prototype.loadGameFonts;
        Scene_Boot.prototype.loadGameFonts = function () {
            if (_Scene_Boot_loadGameFonts) {
                _Scene_Boot_loadGameFonts.call(this);
            }
            FontManager.load(FONT_FAMILY, FONT_FILE);
        };
        var _Game_System_mainFontFace = Game_System.prototype.mainFontFace;
        Game_System.prototype.mainFontFace = function () {
            return FONT_FAMILY + ", " + _Game_System_mainFontFace.call(this);
        };
    } else {
        var _Scene_Boot_create = Scene_Boot.prototype.create;
        Scene_Boot.prototype.create = function () {
            Graphics.loadFont(FONT_FAMILY, "fonts/" + FONT_FILE);
            _Scene_Boot_create.call(this);
        };
        var _Scene_Boot_isGameFontLoaded = Scene_Boot.prototype.isGameFontLoaded;
        Scene_Boot.prototype.isGameFontLoaded = function () {
            if (!_Scene_Boot_isGameFontLoaded.call(this)) {
                return false;
            }
            // Wait for the Arabic font too, but never block the game for long.
            if (Graphics.isFontLoaded(FONT_FAMILY)) {
                return true;
            }
            return Date.now() - this._startDate > 5000;
        };
        var _Window_Base_standardFontFace = Window_Base.prototype.standardFontFace;
        Window_Base.prototype.standardFontFace = function () {
            return FONT_FAMILY + ", " + _Window_Base_standardFontFace.call(this);
        };
    }

    //-------------------------------------------------------------------------
    // Shaping and alignment for every piece of Arabic text drawn
    //-------------------------------------------------------------------------
    var _Bitmap_drawText = Bitmap.prototype.drawText;
    Bitmap.prototype.drawText = function (text, x, y, maxWidth, lineHeight, align) {
        if (!hasArabic(String(text))) {
            return _Bitmap_drawText.apply(this, arguments);
        }
        if (ALIGN_MENUS_RIGHT && !this._vnaKeepAlign && maxWidth && (align === undefined || align === "left")) {
            align = "right";
        }
        var ctx = this._context;
        var old = ctx.direction;
        ctx.direction = "rtl";
        try {
            _Bitmap_drawText.call(this, text, x, y, maxWidth, lineHeight, align);
        } finally {
            ctx.direction = old;
        }
    };

    if (isMZ) {
        // MZ lays out right-to-left messages itself (Utils.containsArabic / textState.rtl).
        if (typeof Utils.containsArabic !== "function") {
            console.warn("VNArabizer_RTL: this MZ version has no built-in right-to-left support.");
        }
        return;
    }

    //-------------------------------------------------------------------------
    // MV: right-to-left message layout
    //
    // MV draws one character at a time, which breaks Arabic letter joining
    // and puts words in left-to-right order. Here each run of text between
    // control codes is redrawn as a whole every time a character is added,
    // anchored at its right edge. Letters join, words flow right-to-left,
    // and the typing effect still works. MV's own x position is kept as a
    // "logical" position and mirrored when drawing.
    //-------------------------------------------------------------------------
    var FULL_WIDTH_WINDOWS = ["Window_Message", "Window_Help", "Window_ChoiceList", "Window_ScrollText"];

    function isFullWidth(win) {
        for (var i = 0; i < FULL_WIDTH_WINDOWS.length; i++) {
            var cls = window[FULL_WIDTH_WINDOWS[i]];
            if (cls && win instanceof cls) {
                return true;
            }
        }
        return false;
    }

    Window_Base.prototype.vnaIsRtl = function (textState) {
        if (textState.vnaRtl === undefined) {
            textState.vnaRtl = hasArabic(textState.text);
        }
        return textState.vnaRtl;
    };

    // Width of the current line (from its start), ignoring control codes.
    Window_Base.prototype.vnaLineWidth = function (textState) {
        var start = textState.text.lastIndexOf("\n", textState.index - 1) + 1;
        var end = textState.text.indexOf("\n", textState.index);
        var line = textState.text.slice(start, end < 0 ? undefined : end);
        var icons = (line.match(/\x1bI\[\d+\]/gi) || []).length;
        line = line.replace(/\x1b[A-Z]+\[[^\]]*\]|\x1b[A-Z]+|\x1b./gi, "");
        return this.textWidth(line) + icons * (Window_Base._iconWidth + 4);
    };

    // Visual right edge that logical x == textState.left maps to.
    Window_Base.prototype.vnaRight = function (textState) {
        if (isFullWidth(this)) {
            var isMessage = typeof Window_Message !== "undefined" && this instanceof Window_Message;
            return this.contents.width - (isMessage ? 0 : textState.left);
        }
        if (textState.vnaLineY !== textState.y) {
            textState.vnaLineY = textState.y;
            textState.vnaLineRight = textState.left + this.vnaLineWidth(textState);
        }
        return textState.vnaLineRight;
    };

    var _Window_Base_processNormalCharacter = Window_Base.prototype.processNormalCharacter;
    Window_Base.prototype.processNormalCharacter = function (textState) {
        if (!this.vnaIsRtl(textState)) {
            return _Window_Base_processNormalCharacter.call(this, textState);
        }
        // A new run starts after a control code, a line break or a new page.
        if (textState.vnaEnd !== textState.index || textState.vnaY !== textState.y || textState.vnaLeft !== textState.left) {
            textState.vnaStart = textState.index;
            textState.vnaX = textState.x;
            textState.vnaW = 0;
        }
        textState.index++;
        var run = textState.text.slice(textState.vnaStart, textState.index);
        var w = this.textWidth(run);
        var anchor = this.vnaRight(textState) - (textState.vnaX - textState.left);
        var c = this.contents;
        if (textState.vnaW > 0) {
            var cx = Math.max(anchor - textState.vnaW - 6, textState.left - 2);
            c.clearRect(cx, textState.y, anchor - cx, textState.height);
        }
        c._vnaKeepAlign = true;
        try {
            c.drawText(run, anchor - w - 4, textState.y, w + 4, textState.height, "right");
        } finally {
            c._vnaKeepAlign = false;
        }
        textState.x = textState.vnaX + w;
        textState.vnaW = w;
        textState.vnaEnd = textState.index;
        textState.vnaY = textState.y;
        textState.vnaLeft = textState.left;
    };

    var _Window_Base_processDrawIcon = Window_Base.prototype.processDrawIcon;
    Window_Base.prototype.processDrawIcon = function (iconIndex, textState) {
        if (!this.vnaIsRtl(textState)) {
            return _Window_Base_processDrawIcon.call(this, iconIndex, textState);
        }
        var w = Window_Base._iconWidth + 4;
        var vx = this.vnaRight(textState) - (textState.x - textState.left) - w;
        this.drawIcon(iconIndex, vx + 2, textState.y + 2);
        textState.x += w;
    };
})();
